def skier_time(s):
    x, y = 0, 0
    visited = set()
    time = 0
    for i in range(len(s)):
        if (x, y) not in visited:
            time += 5
            visited.add((x, y))
        if s[i] == 'N':
            y += 1
        elif s[i] == 'S':
            y -= 1
        elif s[i] == 'E':
            x += 1
        else:
            x -= 1
    return time

